def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    # Cache structure: {key: (value, write_time)}
    cache = OrderedDict()
    results = []

    for op in ops:
        op_type = op[0]
        t = op[1]
        key = op[2]

        # Clean expired entries
        expired_keys = [k for k, (v, write_time) in cache.items() if write_time + ttl <= t]
        for k in expired_keys:
            del cache[k]

        if op_type == 'put':
            value = op[3]

            # Remove key if it exists (to update its position)
            if key in cache:
                del cache[key]
            # If cache is full, evict least recently used
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry as most recently used
            cache[key] = (value, t)

        elif op_type == 'get':
            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

